    self,
    force: bool = False,
    progress_callback: "Callback" = DEFAULT_CALLBACK,
    relink: bool = False,
    filter_info: Optional[str] = None,
    allow_missing: bool = False,
    **kwargs,
) -> Optional[tuple[bool, Optional[bool]]]:
    # callback passed act as a aggregate callback.
    # do not let checkout to call set_size and change progressbar.

    # For version-aware remotes, filter files based on version info
    if self.fs.version_aware and self.meta.version_id:
        version_info = self.get_version_info()
        if version_info:
            # Update filter_info to only include files from this version
            if filter_info:
                filter_info = {k: v for k, v in filter_info.items() 
                             if k in version_info}
            else:
                filter_info = version_info

